// [Blur2PC][macOS] D3D9 larger-depth reuse with bounded real depth/stencil rendering.
#include <display2/device/MetalDevice.h>
#include <display2/context/MetalOcclusion.h>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace Display2;
static void require(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
static std::vector<U8> shader(bool vertex){const std::string metadata=vertex?R"({"parameters":{},"input_semantics":[[0,0,0]],"reflection":{"ubos":[]}})":R"({"parameters":{},"input_semantics":[],"reflection":{"ubos":[]}})";const std::string source="#include <metal_stdlib>\nusing namespace metal;\n"+std::string(vertex?"struct I{float2 p[[attribute(0)]];};struct V{float4 p[[position]];};vertex V blur_main(I i[[stage_in]]){return {float4(i.p,.5,1)};}":"fragment float4 blur_main(){return float4(1,0,0,1);}");const std::string entry="blur_main";std::vector<U8> b(40);std::memcpy(b.data(),"BMSL",4);auto word=[&](U32 p,U32 v){for(U32 i=0;i<4;++i)b[p+i]=U8(v>>(8*i));};word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());b.insert(b.end(),metadata.begin(),metadata.end());b.insert(b.end(),source.begin(),source.end());b.insert(b.end(),entry.begin(),entry.end());word(12,b.size());return b;}
static void pixels(const C_Surface& surface,bool insideRed){auto map=const_cast<C_Surface&>(surface).LockRect(16);require(map.pBits,"Larger-depth colour GPU readback failed");bool good=true;for(U32 y=0;y<24;++y)for(U32 x=0;x<32;++x){U32 actual;std::memcpy(&actual,map.pBits+y*map.pitch+x*4,4);good&=actual==((x<16&&y<12)==insideRed?0xffff0000:0xff000000);}const_cast<C_Surface&>(surface).UnlockRect();require(good,"Bounded depth/stencil clear did not preserve pixels outside the smaller colour target");}
int main(){try{
    C_MetalDevice device;require(device.Create(),"Larger-depth Metal device creation failed");auto& c=device.GetContext();C_VertexShader vs;C_PixelShader ps;C_VertexDeclaration declaration;C_VertexBuffer buffer;auto v=shader(true),p=shader(false);std::string error;require(device.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());require(device.CreatePixelShader(p.size(),p.data(),0,&ps,nullptr,&error),error.c_str());C_VertexFormat format;format.AddElement(0,0,E_VertexElementType_F32_2,E_VertexElementUsage_Position,0);require(device.CreateVertexDeclaration(format,&declaration)&&device.CreateVertexBuffer(32,0,&buffer),"Larger-depth draw geometry failed");const F32 quad[]={-1,1,1,1,-1,-1,1,-1};auto map=buffer.Lock();require(map,"Larger-depth quad upload failed");std::memcpy(map,quad,sizeof(quad));buffer.Unlock();c.SetVertexShader(&vs);c.SetPixelShader(&ps);c.SetVertexBuffer(0,&buffer,0,8,&declaration);c.SetCullMode(E_CullMode_None);c.SetColourWriteEnable(15);c.SetBlendEnable(E_Bool_False);c.SetDepthWriteEnable(E_Bool_False);c.SetDepthFunc(E_CmpFunc_Less);
    for(auto samples:{E_Multisample_None,E_Multisample_2,E_Multisample_4})for(auto depthFormat:{E_SurfaceFormat_D16,E_SurfaceFormat_D24S8}){
        C_Surface large,small,depth;require(device.CreateSurface(32,24,E_Flags_Colour,E_SurfaceFormat_A8R8G8B8,samples,nullptr,&large)&&device.CreateSurface(16,12,E_Flags_Colour,E_SurfaceFormat_A8R8G8B8,samples,nullptr,&small)&&device.CreateSurface(32,24,E_Flags_DepthStencil,depthFormat,samples,nullptr,&depth),"Larger-depth physical attachments failed");c.SetColourSurface(0,&large);c.SetDepthStencilSurface(&depth);C_OcclusionQuery query;require(query.Create(c),"Larger-depth visibility query failed");const bool stencil=depthFormat==E_SurfaceFormat_D24S8;const U32 flags=E_Clear_Colour|E_Clear_Depth|(stencil?E_Clear_Stencil:0);c.BeginScene();query.Begin();c.Clear(flags,0xff000000,.75f,0xa7);c.SetColourSurface(0,&small);c.Clear(flags,0xff112233,.25f,0x3c);c.SetColourSurface(0,&large);c.Clear(E_Clear_Colour,0xff000000);
        c.SetDepthEnable(stencil?E_Bool_False:E_Bool_True);c.SetStencilEnable(stencil?E_Bool_True:E_Bool_False);if(stencil){C_StencilState state;state.SetStencilFunc(E_CmpFunc_Equal);state.SetStencilRef(0x3c);state.SetStencilMask(255);state.SetStencilWriteMask(0);c.SetStencilState(state);}c.DrawPrimitive(E_PrimitiveType_TriangleStrip,0,4);query.End();c.EndScene();U64 count;require(query.GetResult(count)&&count==U64(stencil?16*12:32*24-16*12)*(samples==E_Multisample_None?1:U32(samples)),"Larger-depth clear/query transitions lost exact depth/stencil sample visibility");pixels(large,stencil);
        if(stencil){c.SetStencilEnable(E_Bool_False);c.SetDepthEnable(E_Bool_True);c.BeginScene();c.Clear(E_Clear_Colour,0xff000000);c.DrawPrimitive(E_PrimitiveType_TriangleStrip,0,4);c.EndScene();pixels(large,false);}c.SetDepthStencilSurface(nullptr);c.SetColourSurface(0,nullptr);device.Destroy(&large);device.Destroy(&small);device.Destroy(&depth);
    }
    C_Surface colour,smallDepth,wrongSamples;require(device.CreateSurface(32,24,E_Flags_Colour,E_SurfaceFormat_A8R8G8B8,E_Multisample_None,nullptr,&colour)&&device.CreateSurface(16,12,E_Flags_DepthStencil,E_SurfaceFormat_D16,E_Multisample_None,nullptr,&smallDepth)&&device.CreateSurface(32,24,E_Flags_DepthStencil,E_SurfaceFormat_D16,E_Multisample_2,nullptr,&wrongSamples),"Invalid-depth controls could not allocate real resources");for(auto* depth:{&smallDepth,&wrongSamples,&colour}){c.SetColourSurface(0,&colour);c.SetDepthStencilSurface(depth);c.BeginScene();bool failed=false;try{c.Clear(E_Clear_Colour,0);}catch(const std::logic_error&){failed=true;}require(failed,"Smaller depth, wrong format or mismatched samples were accepted");c.SetDepthStencilSurface(nullptr);c.EndScene();}c.SetColourSurface(0,nullptr);device.Destroy(&colour);device.Destroy(&smallDepth);device.Destroy(&wrongSamples);device.Destroy(&vs);device.Destroy(&ps);device.Destroy(&buffer);device.Destroy(&declaration);require(device.WaitIdle(),"Larger-depth GPU work failed");std::cout<<"Native larger-depth reuse: D16/D24S8 None/2x/4x, bounded depth/stencil clears preserve outside storage, exact real GPU pixels/query samples, invalid-size/format/sample rejection passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
